import React, { useState } from 'react';
import { format } from 'date-fns';
import './Dashboard.css';

const CATEGORY_COLORS = {
  Food:'#fb923c',Transport:'#60a5fa',Entertainment:'#a78bfa',Shopping:'#f472b6',
  Health:'#4ade80',Utilities:'#2dd4bf',Rent:'#c9a84c',Savings:'#34d399',Other:'#94a3b8',
  Salary:'#4ade80',Freelance:'#60a5fa',Bonus:'#c9a84c',
};
const CAT_ICONS = {
  Food:'🍜',Transport:'🚗',Entertainment:'🎬',Shopping:'🛍',Health:'💊',
  Utilities:'⚡',Rent:'🏠',Savings:'💰',Other:'📦',Salary:'💼',Freelance:'💻',Bonus:'🎁',
};

function StatCard({ label, value, sub, color, delay=0, icon }) {
  return (
    <div className="stat-card" style={{ animationDelay: `${delay}ms` }}>
      <div className="stat-header">
        <span className="stat-icon">{icon}</span>
        <span className="stat-label">{label}</span>
      </div>
      <div className="stat-value" style={{ color }}>{value}</div>
      {sub && <div className="stat-sub">{sub}</div>}
      <div className="stat-glow" style={{ background: color }} />
    </div>
  );
}

function MiniBar({ pct, color }) {
  return (
    <div className="mini-bar-track">
      <div className="mini-bar-fill" style={{ width: `${Math.min(pct,100)}%`, background: color }} />
    </div>
  );
}

function EmptyDashboard({ onNavigate }) {
  return (
    <div className="empty-dashboard">
      <div className="empty-dash-orb" />
      <div className="empty-dash-icon">◈</div>
      <h2 className="empty-dash-title">Welcome to Finova</h2>
      <p className="empty-dash-sub">
        You haven't added any transactions yet.<br />
        Start tracking your finances to unlock your dashboard.
      </p>
      <div className="empty-dash-steps">
        <div className="eds-step">
          <div className="eds-num">1</div>
          <div className="eds-text">
            <strong>Add a transaction</strong>
            <span>Record your income or an expense</span>
          </div>
        </div>
        <div className="eds-step">
          <div className="eds-num">2</div>
          <div className="eds-text">
            <strong>Set your budgets</strong>
            <span>Define spending limits per category</span>
          </div>
        </div>
        <div className="eds-step">
          <div className="eds-num">3</div>
          <div className="eds-text">
            <strong>Watch your dashboard come alive</strong>
            <span>Charts, trends, and alerts auto-populate</span>
          </div>
        </div>
      </div>
      {onNavigate && (
        <button className="eds-cta" onClick={() => onNavigate('transactions')}>
          + Add Your First Transaction
        </button>
      )}
    </div>
  );
}

export default function Dashboard({
  totalIncome, totalExpenses, netSavings, savingsRate,
  categoryBreakdown, budgetAlerts, currentTxns, selectedMonth, setSelectedMonth, onNavigate,
}) {
  const fmt = v => `$${v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  const topCategories = Object.entries(categoryBreakdown).sort((a,b)=>b[1]-a[1]).slice(0,5);
  const recentTxns = [...currentTxns].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,6);
  const activeAlerts = budgetAlerts.filter(a=>a.warning||a.over).slice(0,3);

  const months = Array.from({ length: 6 }, (_, i) => {
    const d = new Date();
    d.setMonth(d.getMonth() - i);
    return format(d, 'yyyy-MM');
  });

  // Show empty state if truly no transactions at all (not just this month)
  const isEmpty = currentTxns.length === 0 && totalIncome === 0 && totalExpenses === 0;

  return (
    <div className="dashboard">
      <div className="page-header">
        <div>
          <h1 className="page-title">Dashboard</h1>
          <p className="page-subtitle">Your financial overview at a glance</p>
        </div>
        <select className="month-picker" value={selectedMonth} onChange={e=>setSelectedMonth(e.target.value)}>
          {months.map(m => (
            <option key={m} value={m}>{format(new Date(m+'-01'),'MMMM yyyy')}</option>
          ))}
        </select>
      </div>

      {isEmpty ? (
        <EmptyDashboard onNavigate={onNavigate} />
      ) : (
        <>
          <div className="stats-grid">
            <StatCard label="Total Income" icon="↑" value={fmt(totalIncome)} sub="This month" color="var(--green)" delay={0} />
            <StatCard label="Total Expenses" icon="↓" value={fmt(totalExpenses)} sub="This month" color="var(--red)" delay={80} />
            <StatCard label="Net Savings" icon="◈" value={fmt(netSavings)} sub={netSavings>=0?'Great job!':'Over budget'} color={netSavings>=0?'var(--gold-light)':'var(--red)'} delay={160} />
            <StatCard label="Savings Rate" icon="◎" value={`${savingsRate.toFixed(1)}%`} sub="of income saved" color="var(--teal)" delay={240} />
          </div>

          <div className="mid-row">
            <div className="card category-card">
              <div className="card-title">Spending by Category</div>
              {topCategories.length === 0 ? (
                <div className="empty-state">No expenses recorded this month</div>
              ) : (
                <div className="cat-list">
                  {topCategories.map(([cat,amt]) => (
                    <div key={cat} className="cat-item">
                      <div className="cat-left">
                        <span className="cat-icon">{CAT_ICONS[cat]||'📦'}</span>
                        <span className="cat-name">{cat}</span>
                      </div>
                      <div className="cat-right">
                        <MiniBar pct={(amt/totalExpenses)*100} color={CATEGORY_COLORS[cat]||'#94a3b8'} />
                        <span className="cat-amount" style={{color:CATEGORY_COLORS[cat]}}>{fmt(amt)}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="card alerts-card">
              <div className="card-title">Budget Alerts</div>
              {activeAlerts.length === 0 ? (
                <div className="empty-state all-good">
                  <span className="all-good-icon">✓</span>
                  <span>All budgets on track</span>
                </div>
              ) : (
                <div className="alert-list">
                  {activeAlerts.map(a => (
                    <div key={a.category} className={`alert-item ${a.over?'over':'warning'}`}>
                      <div className="alert-top">
                        <div className="alert-cat">
                          <span>{CAT_ICONS[a.category]||'📦'}</span>
                          <span>{a.category}</span>
                        </div>
                        <span className={`alert-badge ${a.over?'over':'warning'}`}>
                          {a.over?'🔴 Over':'🟡 Near'}
                        </span>
                      </div>
                      <div className="alert-bar-track">
                        <div className="alert-bar-fill" style={{ width:`${Math.min(a.pct,100)}%`, background:a.over?'var(--red)':'var(--gold)' }} />
                      </div>
                      <div className="alert-amounts">
                        <span>${a.spent.toFixed(0)} spent</span>
                        <span>of ${a.limit} limit ({a.pct.toFixed(0)}%)</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="card recent-card">
            <div className="card-title">Recent Transactions</div>
            {recentTxns.length === 0 ? (
              <div className="empty-state">No transactions this month</div>
            ) : (
              <div className="txn-list">
                {recentTxns.map(t => (
                  <div key={t.id} className="txn-row">
                    <div className="txn-icon-wrap" style={{background:`${CATEGORY_COLORS[t.category]||'#94a3b8'}18`}}>
                      <span>{CAT_ICONS[t.category]||'📦'}</span>
                    </div>
                    <div className="txn-info">
                      <span className="txn-desc">{t.description}</span>
                      <span className="txn-cat">{t.category} · {format(new Date(t.date+'T00:00:00'),'MMM d')}</span>
                    </div>
                    <div className={`txn-amount ${t.type}`}>
                      {t.type==='income'?'+':'-'}{fmt(t.amount)}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}
